-- Generated by scripts/build-seed.mjs from data/claims.json. Do not edit by hand.
insert into public.claims
  (id, category, title, exposure, outcome, population, direction, effect, confidence,
   confidence_reasons, summary, triggers, sources, review_status)
values
  ('fiber-chronic-disease', 'nutrient', 'Higher fibre intake lowers the risk of heart disease, type 2 diabetes and bowel cancer', 'Dietary fibre', 'Heart disease, stroke, type 2 diabetes, bowel cancer and early death', 'Healthy adults', 'decreases', 'Eating 25-29 g a day was linked to 15-30% lower risk of early death and several chronic diseases compared with the lowest intakes, with further benefit above 30 g.', 'moderate', 'Large, consistent body of cohort studies with a dose-response relationship, supported by trials showing improvements in weight, blood pressure and cholesterol.', 'People who eat more fibre from whole grains, vegetables, fruit and legumes have less heart disease, type 2 diabetes and bowel cancer. Most people eat well under the 25-30 g a day linked to the biggest benefit.', '[{"signal":"fiber_g_per_day","op":"<","value":20,"stance":"gap"},{"signal":"fiber_g_per_day","op":">=","value":25,"stance":"strength"}]'::jsonb, '[{"citation":"Reynolds A et al. Carbohydrate quality and human health: a series of systematic reviews and meta-analyses. Lancet, 2019","design":"Meta-analysis of cohorts and trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Reynolds%20carbohydrate%20quality%20and%20human%20health%20systematic%20reviews%20meta-analyses%20Lancet%202019"}]'::jsonb, 'draft'),
  ('processed-meat-colorectal', 'food', 'Processed meat raises the risk of bowel cancer', 'Processed meat (bacon, ham, sausages, salami, hot dogs)', 'Colorectal cancer', 'Adults', 'increases', 'Each 50 g a day (about two slices of ham) is linked to roughly 18% higher bowel cancer risk.', 'high', 'Classified as a cause of cancer (Group 1) by the WHO''s International Agency for Research on Cancer, based on consistent evidence from many large studies.', 'Processed meat is classed as a cause of bowel cancer. The risk rises with the amount eaten, so less is better and there is no amount known to be beneficial.', '[{"signal":"processed_meat_servings_per_week","op":">=","value":3,"stance":"gap"},{"signal":"processed_meat_servings_per_week","op":"<","value":1,"stance":"strength"}]'::jsonb, '[{"citation":"Bouvard V et al. Carcinogenicity of consumption of red and processed meat. Lancet Oncology, 2015 (IARC Monograph Working Group)","design":"Expert evaluation of the full evidence base","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Bouvard%20carcinogenicity%20of%20consumption%20of%20red%20and%20processed%20meat%20Lancet%20Oncol%202015"}]'::jsonb, 'draft'),
  ('red-meat-colorectal', 'food', 'High red meat intake probably raises the risk of bowel cancer', 'Unprocessed red meat (beef, pork, lamb)', 'Colorectal cancer', 'Adults', 'increases', 'Risk appears to rise with intake; cancer research bodies advise keeping red meat to about 350-500 g cooked weight a week.', 'low', 'Classed as ''probably carcinogenic'' (Group 2A). The association is smaller and less certain than for processed meat, and some reviews rate the certainty as low.', 'Moderate amounts of red meat are a good source of protein, iron and B12, but eating a lot is probably linked to higher bowel cancer risk. The evidence is weaker than for processed meat.', '[{"signal":"red_meat_servings_per_week","op":">","value":5,"stance":"gap"}]'::jsonb, '[{"citation":"Bouvard V et al. Carcinogenicity of consumption of red and processed meat. Lancet Oncology, 2015","design":"Expert evaluation of the full evidence base","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Bouvard%20carcinogenicity%20of%20consumption%20of%20red%20and%20processed%20meat%20Lancet%20Oncol%202015"},{"citation":"Zeraatkar D et al. Red and processed meat consumption and risk for all-cause mortality and cardiometabolic outcomes. Annals of Internal Medicine, 2019","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Zeraatkar%20red%20and%20processed%20meat%20consumption%20all-cause%20mortality%20cardiometabolic%20outcomes%20Ann%20Intern%20Med%202019"}]'::jsonb, 'draft'),
  ('sugary-drinks-diabetes', 'food', 'Sugary drinks raise the risk of type 2 diabetes and weight gain', 'Sugar-sweetened beverages (soda, sweetened juice drinks, energy drinks)', 'Type 2 diabetes and weight gain', 'Adults', 'increases', 'Each daily serving was linked to about 18% higher risk of type 2 diabetes, independent of body weight.', 'moderate', 'Consistent cohort evidence with a dose-response relationship, supported by trials in which replacing sugary drinks reduced weight gain.', 'Sugary drinks add sugar without making you feel full. Regular intake is consistently linked to type 2 diabetes and weight gain. Water, sparkling water, tea and coffee are easy swaps.', '[{"signal":"sugary_drink_servings_per_week","op":">=","value":3,"stance":"gap"},{"signal":"sugary_drink_servings_per_week","op":"<","value":1,"stance":"strength"}]'::jsonb, '[{"citation":"Imamura F et al. Consumption of sugar sweetened beverages, artificially sweetened beverages, and fruit juice and incidence of type 2 diabetes. BMJ, 2015","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Imamura%20consumption%20of%20sugar%20sweetened%20beverages%20incidence%20of%20type%202%20diabetes%20BMJ%202015"},{"citation":"Malik VS et al. Sugar-sweetened beverages and weight gain in children and adults: a systematic review and meta-analysis. Am J Clin Nutr, 2013","design":"Meta-analysis of trials and cohorts","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Malik%20sugar-sweetened%20beverages%20and%20weight%20gain%20children%20adults%20meta-analysis%202013"}]'::jsonb, 'draft'),
  ('fruit-veg-mortality', 'food', 'Eating more fruit and vegetables lowers the risk of heart disease and early death', 'Fruit and vegetables', 'Heart disease, stroke, cancer and early death', 'Adults', 'decreases', 'About 5 servings a day (2 fruit, 3 vegetables) was linked to the lowest risk of early death, with little extra benefit beyond that.', 'moderate', 'Very large, consistent cohort evidence with a clear dose-response relationship. Few long-term trials exist.', 'People who eat around five servings of fruit and vegetables a day live longer and have less heart disease. Starchy potatoes and fruit juice don''t show the same benefit.', '[{"signal":"fruit_veg_servings_per_day","op":"<","value":3,"stance":"gap"},{"signal":"fruit_veg_servings_per_day","op":">=","value":5,"stance":"strength"}]'::jsonb, '[{"citation":"Aune D et al. Fruit and vegetable intake and the risk of cardiovascular disease, total cancer and all-cause mortality. Int J Epidemiol, 2017","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Aune%20fruit%20and%20vegetable%20intake%20risk%20of%20cardiovascular%20disease%20total%20cancer%20all-cause%20mortality%202017"},{"citation":"Wang DD et al. Fruit and vegetable intake and mortality. Circulation, 2021","design":"Two large cohorts plus meta-analysis","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Wang%20fruit%20and%20vegetable%20intake%20and%20mortality%20Circulation%202021"}]'::jsonb, 'draft'),
  ('whole-grains-cvd', 'food', 'Whole grains lower the risk of heart disease and early death', 'Whole grains (oats, brown rice, wholemeal bread, whole-wheat pasta)', 'Heart disease, stroke, type 2 diabetes and early death', 'Adults', 'decreases', 'About 90 g a day of whole grains (roughly three servings) was linked to around 20% lower risk of heart disease and early death.', 'moderate', 'Consistent cohort evidence with dose-response, supported by trials showing improved cholesterol and weight.', 'Swapping refined grains for whole grains is one of the easiest evidence-backed changes. Benefits are seen at around three servings a day.', '[{"signal":"whole_grain_servings_per_day","op":">=","value":3,"stance":"strength"},{"signal":"whole_grain_servings_per_day","op":"<","value":1,"stance":"gap"}]'::jsonb, '[{"citation":"Aune D et al. Whole grain consumption and risk of cardiovascular disease, cancer, and all cause and cause specific mortality. BMJ, 2016","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Aune%20whole%20grain%20consumption%20risk%20cardiovascular%20disease%20cancer%20mortality%20BMJ%202016"},{"citation":"Reynolds A et al. Carbohydrate quality and human health. Lancet, 2019","design":"Meta-analysis of cohorts and trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Reynolds%20carbohydrate%20quality%20and%20human%20health%20Lancet%202019"}]'::jsonb, 'draft'),
  ('legumes-ldl', 'food', 'Beans, lentils and chickpeas lower LDL cholesterol', 'Legumes (pulses)', 'LDL cholesterol', 'Adults', 'decreases', 'About one serving a day (around 130 g) lowered LDL cholesterol by roughly 5% in trials.', 'moderate', 'Meta-analysis of randomised trials; outcome is a risk marker (cholesterol) rather than heart attacks themselves.', 'Legumes are cheap, high in fibre and protein, and lower ''bad'' LDL cholesterol in controlled trials. They are one of the easiest ways to add fibre.', '[{"signal":"legume_servings_per_week","op":">=","value":3,"stance":"strength"},{"signal":"legume_servings_per_week","op":"<","value":1,"stance":"gap"}]'::jsonb, '[{"citation":"Ha V et al. Effect of dietary pulse intake on established therapeutic lipid targets for cardiovascular risk reduction. CMAJ, 2014","design":"Meta-analysis of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Ha%20effect%20of%20dietary%20pulse%20intake%20on%20established%20therapeutic%20lipid%20targets%20CMAJ%202014"}]'::jsonb, 'draft'),
  ('nuts-cvd', 'food', 'A daily handful of nuts is linked to lower heart disease risk', 'Nuts and seeds', 'Heart disease and early death', 'Adults', 'decreases', 'About 28 g a day (a small handful) was linked to around 20% lower risk of heart disease and early death.', 'moderate', 'Consistent cohort evidence with dose-response, supported by a large trial (PREDIMED) in which a nut-supplemented Mediterranean diet reduced cardiovascular events.', 'Despite being calorie-dense, regular nut eaters do not gain more weight and have less heart disease. Unsalted nuts are a strong evidence-backed snack.', '[{"signal":"nut_servings_per_week","op":">=","value":3,"stance":"strength"}]'::jsonb, '[{"citation":"Aune D et al. Nut consumption and risk of cardiovascular disease, total cancer, all-cause and cause-specific mortality. BMC Medicine, 2016","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Aune%20nut%20consumption%20risk%20cardiovascular%20disease%20total%20cancer%20mortality%20BMC%20Med%202016"}]'::jsonb, 'draft'),
  ('fish-heart', 'food', 'Eating fish about twice a week is linked to fewer heart disease deaths', 'Fish, especially oily fish (salmon, sardines, mackerel)', 'Death from coronary heart disease', 'Adults', 'decreases', 'One to two servings of oily fish a week was linked to lower risk of dying from heart disease.', 'moderate', 'Consistent cohort evidence and biological plausibility; recommended by major dietary guidelines. Supplement trials do not show the same benefit.', 'Major guidelines recommend about two servings of fish a week, ideally oily fish. The benefit appears to come from eating fish rather than taking fish oil pills.', '[{"signal":"fish_servings_per_week","op":">=","value":2,"stance":"strength"}]'::jsonb, '[{"citation":"Mozaffarian D, Rimm EB. Fish intake, contaminants, and human health: evaluating the risks and the benefits. JAMA, 2006","design":"Systematic review","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Mozaffarian%20Rimm%20fish%20intake%20contaminants%20human%20health%20JAMA%202006"}]'::jsonb, 'draft'),
  ('ultra-processed-health', 'food', 'Diets high in ultra-processed food are linked to worse health and make people eat more', 'Ultra-processed foods (NOVA group 4)', 'Early death, heart disease, type 2 diabetes, weight gain', 'Adults', 'increases', 'In a controlled trial people ate about 500 kcal a day more on an ultra-processed diet than on an unprocessed one. Large reviews link higher intake to higher risk of several chronic diseases.', 'moderate', 'Consistent observational evidence across many outcomes plus one tightly controlled inpatient trial. ''Ultra-processed'' is a broad category and not all such foods are equally harmful.', 'Ultra-processed foods are easy to overeat, and diets built around them are linked to worse health. You don''t need to avoid them completely; shifting the balance toward whole foods matters most.', '[{"signal":"ultra_processed_kcal_share","op":">=","value":0.5,"stance":"gap"},{"signal":"ultra_processed_kcal_share","op":"<=","value":0.2,"stance":"strength"}]'::jsonb, '[{"citation":"Hall KD et al. Ultra-processed diets cause excess calorie intake and weight gain: an inpatient randomized controlled trial of ad libitum food intake. Cell Metabolism, 2019","design":"Randomised controlled trial (20 adults, inpatient)","tier":4,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Hall%20ultra-processed%20diets%20cause%20excess%20calorie%20intake%20and%20weight%20gain%20inpatient%20randomized%20controlled%20trial%20Cell%20Metab%202019"},{"citation":"Lane MM et al. Ultra-processed food exposure and adverse health outcomes: umbrella review of epidemiological meta-analyses. BMJ, 2024","design":"Umbrella review of meta-analyses","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Lane%20ultra-processed%20food%20exposure%20adverse%20health%20outcomes%20umbrella%20review%20BMJ%202024"}]'::jsonb, 'draft'),
  ('sodium-blood-pressure', 'nutrient', 'Eating less salt lowers blood pressure and cardiovascular risk', 'Sodium (salt)', 'Blood pressure, stroke and cardiovascular events', 'Adults, especially those with raised blood pressure', 'increases', 'Reducing salt intake lowers blood pressure in trials, and a large trial of salt substitutes reduced strokes, cardiovascular events and deaths.', 'high', 'Many randomised trials on blood pressure plus a large outcome trial. Note: sodium estimates from photos are unreliable because salt is invisible.', 'Most people eat more salt than recommended, mainly from bread, processed and restaurant food. Cutting back lowers blood pressure. Your logged sodium is likely an underestimate.', '[{"signal":"sodium_mg_per_day","op":">","value":2300,"stance":"gap"}]'::jsonb, '[{"citation":"He FJ, Li J, MacGregor GA. Effect of longer term modest salt reduction on blood pressure. BMJ, 2013","design":"Meta-analysis of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=He%20Li%20MacGregor%20effect%20of%20longer%20term%20modest%20salt%20reduction%20on%20blood%20pressure%20BMJ%202013"},{"citation":"Neal B et al. Effect of salt substitution on cardiovascular events and death. NEJM, 2021","design":"Randomised controlled trial (about 21,000 adults)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Neal%20effect%20of%20salt%20substitution%20on%20cardiovascular%20events%20and%20death%20N%20Engl%20J%20Med%202021"}]'::jsonb, 'draft'),
  ('saturated-fat-replacement', 'nutrient', 'Replacing saturated fat with unsaturated fat lowers cardiovascular events', 'Saturated fat (butter, fatty meat, cheese, coconut and palm oil)', 'Cardiovascular events', 'Adults', 'increases', 'Cutting saturated fat for at least two years reduced combined cardiovascular events by about 17%, with the clearest benefit when it was replaced by polyunsaturated fat.', 'moderate', 'Cochrane review of randomised trials; benefit depends on what replaces the saturated fat (refined carbohydrates show no benefit).', 'What you replace saturated fat with matters. Swapping butter and fatty meat for olive oil, nuts, seeds and fish lowers heart disease risk; swapping it for refined carbs doesn''t.', '[{"signal":"saturated_fat_pct_kcal","op":">","value":10,"stance":"gap"},{"signal":"saturated_fat_pct_kcal","op":"<=","value":10,"stance":"strength"}]'::jsonb, '[{"citation":"Hooper L et al. Reduction in saturated fat intake for cardiovascular disease. Cochrane Database of Systematic Reviews, 2020","design":"Cochrane systematic review of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Hooper%20reduction%20in%20saturated%20fat%20intake%20for%20cardiovascular%20disease%20Cochrane%202020"}]'::jsonb, 'draft'),
  ('added-sugar-limit', 'nutrient', 'Keeping free sugars under 10% of calories reduces weight gain and tooth decay', 'Free and added sugars', 'Body weight and dental caries', 'Adults and children', 'increases', 'WHO strongly recommends free sugars below 10% of daily energy, and suggests below 5% for further benefit.', 'moderate', 'WHO guideline based on systematic reviews of trials and cohort studies (moderate-quality evidence).', 'Free sugars (added sugar, honey, syrups and juice) should be under 10% of calories, about 50 g on a 2,000 kcal diet. Sugar in whole fruit doesn''t count.', '[{"signal":"added_sugar_pct_kcal","op":">","value":10,"stance":"gap"}]'::jsonb, '[{"citation":"World Health Organization. Guideline: Sugars intake for adults and children, 2015","design":"WHO guideline","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=WHO%20guideline%20sugars%20intake%20for%20adults%20and%20children%202015"}]'::jsonb, 'draft'),
  ('seed-oils-inflammation', 'fad', 'Seed oils (linoleic acid) do not cause inflammation or heart disease', 'Linoleic acid from seed oils (soybean, sunflower, corn, canola)', 'Inflammation and heart disease', 'Adults', 'decreases', 'Higher linoleic acid intake and blood levels are linked to lower, not higher, heart disease risk; trials show it does not raise inflammatory markers.', 'moderate', 'Consistent cohort studies, including objective blood biomarkers, plus a systematic review of controlled feeding trials on inflammation.', 'The claim that seed oils are ''toxic'' or inflammatory is not supported. Linoleic acid is linked to lower heart disease risk. Deep-fried food is a separate concern, mostly because of what is being fried.', '[]'::jsonb, '[{"citation":"Farvid MS et al. Dietary linoleic acid and risk of coronary heart disease: a systematic review and meta-analysis of prospective cohort studies. Circulation, 2014","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Farvid%20dietary%20linoleic%20acid%20risk%20of%20coronary%20heart%20disease%20meta-analysis%20Circulation%202014"},{"citation":"Marklund M et al. Biomarkers of dietary omega-6 fatty acids and incident cardiovascular disease and mortality. Circulation, 2019","design":"Pooled analysis of 30 cohorts using blood biomarkers","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Marklund%20biomarkers%20of%20dietary%20omega-6%20fatty%20acids%20incident%20cardiovascular%20disease%20mortality%20Circulation%202019"},{"citation":"Johnson GH, Fritsche K. Effect of dietary linoleic acid on markers of inflammation in healthy persons: a systematic review of randomized controlled trials. J Acad Nutr Diet, 2012","design":"Systematic review of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Johnson%20Fritsche%20effect%20of%20dietary%20linoleic%20acid%20on%20markers%20of%20inflammation%20systematic%20review%202012"}]'::jsonb, 'draft'),
  ('intermittent-fasting-weight', 'timing', 'Intermittent fasting works for weight loss about as well as ordinary calorie cutting', 'Time-restricted eating and intermittent fasting', 'Weight loss', 'Adults with overweight or obesity', 'no_effect', 'In a 12-month trial, adding an 8-hour eating window to calorie restriction gave no extra weight loss over calorie restriction alone.', 'moderate', 'Several randomised trials, including a 12-month trial, consistently find no advantage beyond eating fewer calories.', 'Fasting windows help some people eat less, which is why they can work. There is no good evidence of special metabolic benefits beyond that. Pick it if it suits your routine.', '[]'::jsonb, '[{"citation":"Liu D et al. Calorie restriction with or without time-restricted eating in weight loss. NEJM, 2022","design":"Randomised controlled trial (139 adults, 12 months)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Liu%20calorie%20restriction%20with%20or%20without%20time-restricted%20eating%20in%20weight%20loss%20N%20Engl%20J%20Med%202022"},{"citation":"Lowe DA et al. Effects of time-restricted eating on weight loss and other metabolic parameters (TREAT). JAMA Internal Medicine, 2020","design":"Randomised controlled trial (116 adults, 12 weeks)","tier":4,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Lowe%20effects%20of%20time-restricted%20eating%20on%20weight%20loss%20TREAT%20randomized%20clinical%20trial%20JAMA%20Intern%20Med%202020"}]'::jsonb, 'draft'),
  ('low-carb-vs-low-fat', 'diet', 'Low-carb and low-fat diets give similar weight loss after a year', 'Low-carbohydrate or ketogenic diets', 'Weight loss at 12 months', 'Adults with overweight', 'no_effect', 'In a 12-month trial of over 600 adults, healthy low-carb and healthy low-fat diets produced no significant difference in weight loss.', 'moderate', 'Large randomised trial consistent with meta-analyses; short-term low-carb advantages largely disappear by one year.', 'Low-carb can work, but not better than other diets in the long run. The diet you can stick to, built on whole foods, matters more than the carb-fat split.', '[]'::jsonb, '[{"citation":"Gardner CD et al. Effect of low-fat vs low-carbohydrate diet on 12-month weight loss in overweight adults (DIETFITS). JAMA, 2018","design":"Randomised controlled trial (609 adults, 12 months)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Gardner%20effect%20of%20low-fat%20vs%20low-carbohydrate%20diet%20on%2012-month%20weight%20loss%20DIETFITS%20JAMA%202018"}]'::jsonb, 'draft'),
  ('mediterranean-cvd', 'diet', 'A Mediterranean diet reduces heart attacks and strokes', 'Mediterranean diet (vegetables, legumes, whole grains, olive oil, nuts, fish)', 'Major cardiovascular events', 'Adults at high cardiovascular risk', 'decreases', 'In the PREDIMED trial, a Mediterranean diet with extra olive oil or nuts reduced major cardiovascular events by about 30%.', 'moderate', 'Large randomised trials (PREDIMED, re-analysed after randomisation problems were found, and CORDIOPREV) plus consistent cohort evidence.', 'The Mediterranean pattern has some of the strongest trial evidence of any diet for preventing heart disease.', '[]'::jsonb, '[{"citation":"Estruch R et al. Primary prevention of cardiovascular disease with a Mediterranean diet supplemented with extra-virgin olive oil or nuts. NEJM, 2018","design":"Randomised controlled trial (about 7,400 adults)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Estruch%20primary%20prevention%20of%20cardiovascular%20disease%20Mediterranean%20diet%20extra-virgin%20olive%20oil%20or%20nuts%202018"},{"citation":"Delgado-Lista J et al. Long-term secondary prevention of cardiovascular disease with a Mediterranean diet and a low-fat diet (CORDIOPREV). Lancet, 2022","design":"Randomised controlled trial (about 1,000 adults with heart disease)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Delgado-Lista%20CORDIOPREV%20secondary%20prevention%20Mediterranean%20diet%20low-fat%20diet%20Lancet%202022"}]'::jsonb, 'draft'),
  ('dash-blood-pressure', 'diet', 'The DASH diet lowers blood pressure', 'DASH diet (fruit, vegetables, low-fat dairy, whole grains, less salt)', 'Blood pressure', 'Adults with normal or raised blood pressure', 'decreases', 'DASH combined with lower salt reduced blood pressure substantially in controlled feeding trials, most in people with hypertension.', 'high', 'Multiple well-controlled randomised feeding trials with consistent results.', 'DASH is one of the best-proven eating patterns for lowering blood pressure, especially with less salt.', '[]'::jsonb, '[{"citation":"Sacks FM et al. Effects on blood pressure of reduced dietary sodium and the Dietary Approaches to Stop Hypertension (DASH) diet. NEJM, 2001","design":"Randomised controlled feeding trial","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Sacks%20effects%20on%20blood%20pressure%20of%20reduced%20dietary%20sodium%20and%20the%20DASH%20diet%20N%20Engl%20J%20Med%202001"}]'::jsonb, 'draft'),
  ('carnivore-long-term', 'diet', 'There is no long-term evidence that a carnivore diet is safe or beneficial', 'Carnivore (all-meat) diet', 'Long-term health', 'Adults', 'unclear', 'No randomised trials exist. The main study is a self-reported online survey of followers.', 'very_low', 'Evidence is limited to a self-selected survey and anecdotes; no controlled studies or long-term follow-up.', 'Claims about carnivore diets rest on personal stories, not trials. It removes fibre entirely and usually raises processed meat and saturated fat, which have well-established risks.', '[]'::jsonb, '[{"citation":"Lennerz BS et al. Behavioral characteristics and self-reported health status among 2029 adults consuming a ''carnivore diet''. Current Developments in Nutrition, 2021","design":"Self-reported online survey","tier":5,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Lennerz%20behavioral%20characteristics%20self-reported%20health%20status%20adults%20consuming%20carnivore%20diet%202021"}]'::jsonb, 'draft'),
  ('paleo-short-term', 'diet', 'Paleo diets show short-term benefits but have no long-term trials', 'Paleolithic diet', 'Metabolic risk markers', 'Adults', 'decreases', 'Small, short trials found improvements in waist size, blood pressure and blood fats, largely in line with eating fewer processed foods.', 'low', 'Few small trials lasting weeks to months; no long-term outcome data.', 'Paleo''s benefits likely come from cutting processed food and eating more vegetables. Excluding whole grains and legumes isn''t supported by evidence.', '[]'::jsonb, '[{"citation":"Manheimer EW et al. Paleolithic nutrition for metabolic syndrome: systematic review and meta-analysis. Am J Clin Nutr, 2015","design":"Meta-analysis of small randomised trials","tier":4,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Manheimer%20paleolithic%20nutrition%20for%20metabolic%20syndrome%20systematic%20review%20meta-analysis%202015"}]'::jsonb, 'draft'),
  ('vegetarian-heart', 'diet', 'Vegetarian diets are linked to lower heart disease risk', 'Vegetarian and vegan diets', 'Ischaemic heart disease and stroke', 'Adults', 'decreases', 'In a large UK cohort, vegetarians had about 22% lower heart disease risk but a higher risk of haemorrhagic stroke.', 'low', 'Observational evidence from large cohorts; vegetarians differ from others in many lifestyle habits.', 'Well-planned vegetarian diets are linked to less heart disease. Nutrients to watch are B12, iodine, iron and omega-3.', '[]'::jsonb, '[{"citation":"Tong TYN et al. Risks of ischaemic heart disease and stroke in meat eaters, fish eaters, and vegetarians over 18 years of follow-up (EPIC-Oxford). BMJ, 2019","design":"Prospective cohort (about 48,000 adults)","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Tong%20risks%20of%20ischaemic%20heart%20disease%20and%20stroke%20in%20meat%20eaters%20fish%20eaters%20vegetarians%20EPIC-Oxford%20BMJ%202019"}]'::jsonb, 'draft'),
  ('vegan-b12', 'supplement', 'People eating vegan diets need a reliable source of vitamin B12', 'Vitamin B12 from fortified foods or supplements', 'B12 deficiency (anaemia, nerve damage)', 'People eating vegan or mostly plant-based diets', 'decreases', 'Vitamin B12 is found almost only in animal foods; without fortified foods or a supplement, deficiency is common in vegans.', 'high', 'Established physiology and consistent guidance from dietetic associations and health authorities.', 'If you eat few or no animal foods, take a B12 supplement or eat B12-fortified foods every day.', '[{"signal":"b12_pct_target","op":"<","value":50,"stance":"info"}]'::jsonb, '[{"citation":"Melina V et al. Position of the Academy of Nutrition and Dietetics: vegetarian diets. J Acad Nutr Diet, 2016","design":"Professional position statement","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Melina%20position%20of%20the%20Academy%20of%20Nutrition%20and%20Dietetics%20vegetarian%20diets%202016"}]'::jsonb, 'draft'),
  ('vitamin-d-supplements', 'supplement', 'Vitamin D supplements do not prevent cancer or heart disease in healthy adults', 'Vitamin D supplements (2,000 IU a day)', 'Cancer and cardiovascular events', 'Healthy adults without deficiency', 'no_effect', 'In a trial of about 26,000 adults over five years, vitamin D did not lower cancer or cardiovascular events.', 'high', 'Large, long randomised controlled trial consistent with other trials.', 'Vitamin D supplements don''t prevent cancer or heart disease in people who aren''t deficient. They are still worth taking if you are deficient, get little sun, or have been advised to by a clinician.', '[{"signal":"vitamin_d_pct_target","op":"<","value":50,"stance":"info"}]'::jsonb, '[{"citation":"Manson JE et al. Vitamin D supplements and prevention of cancer and cardiovascular disease (VITAL). NEJM, 2019","design":"Randomised controlled trial (25,871 adults)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Manson%20vitamin%20D%20supplements%20and%20prevention%20of%20cancer%20and%20cardiovascular%20disease%20VITAL%202019"}]'::jsonb, 'draft'),
  ('omega3-supplements', 'supplement', 'Fish oil supplements do little to prevent heart disease in most people', 'Omega-3 (fish oil) supplements', 'Cardiovascular events and death', 'Adults', 'no_effect', 'Large trials and a Cochrane review found little or no effect on heart attacks, strokes or death for standard-dose fish oil.', 'high', 'Large randomised trials and a Cochrane review of 86 trials rated at moderate-to-high certainty.', 'Eating fish is linked to heart benefits, but fish oil capsules mostly aren''t. Prescription high-dose formulations for specific patients are a separate question for a doctor.', '[{"signal":"fish_servings_per_week","op":"<","value":1,"stance":"info"}]'::jsonb, '[{"citation":"Abdelhamid AS et al. Omega-3 fatty acids for the primary and secondary prevention of cardiovascular disease. Cochrane Database of Systematic Reviews, 2020","design":"Cochrane systematic review of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Abdelhamid%20omega-3%20fatty%20acids%20primary%20secondary%20prevention%20cardiovascular%20disease%20Cochrane%202020"},{"citation":"Manson JE et al. Marine n-3 fatty acids and prevention of cardiovascular disease and cancer (VITAL). NEJM, 2019","design":"Randomised controlled trial (25,871 adults)","tier":2,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Manson%20marine%20n-3%20fatty%20acids%20prevention%20of%20cardiovascular%20disease%20and%20cancer%202019"}]'::jsonb, 'draft'),
  ('multivitamins', 'supplement', 'Multivitamins have not been shown to prevent heart disease or cancer', 'Multivitamin and mineral supplements', 'Cardiovascular disease, cancer and death', 'Healthy, non-pregnant adults', 'no_effect', 'The US Preventive Services Task Force found insufficient evidence of benefit, and recommends against beta-carotene and vitamin E supplements for prevention.', 'moderate', 'Systematic review of randomised trials by a national guideline body.', 'A multivitamin won''t make up for a poor diet or prevent chronic disease. Specific supplements make sense for specific needs, such as folic acid in pregnancy or B12 for vegans.', '[]'::jsonb, '[{"citation":"US Preventive Services Task Force. Vitamin, mineral, and multivitamin supplementation to prevent cardiovascular disease and cancer: recommendation statement. JAMA, 2022","design":"Guideline based on systematic review","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=USPSTF%20vitamin%20mineral%20multivitamin%20supplementation%20prevent%20cardiovascular%20disease%20cancer%20JAMA%202022"}]'::jsonb, 'draft'),
  ('eggs-heart', 'food', 'Up to an egg a day is not linked to higher heart disease risk for most people', 'Eggs', 'Cardiovascular disease', 'Adults (evidence less clear for people with type 2 diabetes)', 'no_effect', 'In three large US cohorts plus a meta-analysis, eating up to one egg a day was not associated with higher cardiovascular risk.', 'low', 'Observational evidence; some studies disagree, especially at higher intakes.', 'Moderate egg intake looks fine for most people. What you eat with them, such as bacon and white toast, matters more.', '[]'::jsonb, '[{"citation":"Drouin-Chartier JP et al. Egg consumption and risk of cardiovascular disease: three large prospective US cohort studies, systematic review, and updated meta-analysis. BMJ, 2020","design":"Cohorts plus meta-analysis","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Drouin-Chartier%20egg%20consumption%20risk%20of%20cardiovascular%20disease%20three%20large%20prospective%20US%20cohort%20BMJ%202020"}]'::jsonb, 'draft'),
  ('protein-muscle', 'nutrient', 'Extra protein boosts muscle gains from strength training, up to about 1.6 g per kg', 'Protein intake above the basic recommendation', 'Muscle mass and strength with resistance training', 'Adults doing resistance training', 'increases', 'Protein supplementation increased gains in lean mass, with benefits levelling off at about 1.6 g per kg of body weight per day.', 'moderate', 'Meta-analysis of 49 randomised trials; effects are modest.', 'If you lift weights, eating around 1.6 g of protein per kg of body weight a day helps a little. Beyond that there is little extra benefit.', '[]'::jsonb, '[{"citation":"Morton RW et al. A systematic review, meta-analysis and meta-regression of the effect of protein supplementation on resistance training-induced gains in muscle mass and strength. Br J Sports Med, 2018","design":"Meta-analysis of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Morton%20protein%20supplementation%20resistance%20training-induced%20gains%20muscle%20mass%20strength%20meta-regression%202018"}]'::jsonb, 'draft'),
  ('protein-timing', 'timing', 'Total daily protein matters more than an ''anabolic window'' after workouts', 'Timing of protein around exercise', 'Muscle growth and strength', 'Adults doing resistance training', 'no_effect', 'Once total daily protein was accounted for, timing protein right after training made no significant difference.', 'low', 'Meta-analysis of a limited number of small trials.', 'There''s no need to rush a protein shake after training. Hitting your total protein across the day is what counts.', '[]'::jsonb, '[{"citation":"Schoenfeld BJ, Aragon AA, Krieger JW. The effect of protein timing on muscle strength and hypertrophy: a meta-analysis. J Int Soc Sports Nutr, 2013","design":"Meta-analysis of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Schoenfeld%20Aragon%20Krieger%20effect%20of%20protein%20timing%20on%20muscle%20strength%20and%20hypertrophy%20meta-analysis%202013"}]'::jsonb, 'draft'),
  ('detox-diets', 'fad', 'There is no good evidence that detox diets or juice cleanses remove toxins', 'Detox diets, juice cleanses, detox teas', 'Toxin removal and weight', 'Adults', 'no_effect', 'A systematic review found no rigorous clinical evidence that commercial detox diets remove toxins; any weight lost is regained.', 'low', 'Very few studies exist and they are small and poorly controlled; the claims themselves are rarely specific enough to test.', 'Your liver and kidneys already handle detoxification. Detox products don''t name which toxins they remove or show that they do.', '[]'::jsonb, '[{"citation":"Klein AV, Kiat H. Detox diets for toxin elimination and weight management: a critical review of the evidence. J Hum Nutr Diet, 2015","design":"Systematic review","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Klein%20Kiat%20detox%20diets%20for%20toxin%20elimination%20and%20weight%20management%20critical%20review%202015"}]'::jsonb, 'draft'),
  ('alkaline-diet-cancer', 'fad', 'Alkaline diets and alkaline water do not prevent or treat cancer', 'Alkaline diet or alkaline water', 'Cancer prevention and treatment', 'Adults', 'no_effect', 'A systematic review found no studies supporting an alkaline diet for cancer; food cannot meaningfully change blood pH.', 'low', 'The absence of supporting evidence plus well-established physiology of blood pH regulation.', 'Your body tightly controls blood pH regardless of what you eat. The vegetable-heavy part of ''alkaline'' diets is healthy; the pH theory isn''t.', '[]'::jsonb, '[{"citation":"Fenton TR, Huang T. Systematic review of the association between dietary acid load, alkaline water and cancer. BMJ Open, 2016","design":"Systematic review","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Fenton%20Huang%20systematic%20review%20association%20dietary%20acid%20load%20alkaline%20water%20and%20cancer%20BMJ%20Open%202016"}]'::jsonb, 'draft'),
  ('sweeteners-weight', 'food', 'Non-sugar sweeteners don''t help with long-term weight control', 'Non-sugar sweeteners (aspartame, sucralose, stevia and others)', 'Long-term body weight and chronic disease', 'Adults and children without diabetes', 'no_effect', 'WHO advises against using non-sugar sweeteners for weight control; long-term use was linked in observational studies to slightly higher risk of type 2 diabetes and heart disease.', 'low', 'Conditional WHO recommendation based on low-certainty evidence.', 'Diet drinks are better than sugary ones, but sweeteners don''t help much with weight in the long run. Water is the better default.', '[]'::jsonb, '[{"citation":"World Health Organization. Use of non-sugar sweeteners: WHO guideline, 2023","design":"WHO guideline","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=WHO%20guideline%20use%20of%20non-sugar%20sweeteners%202023"}]'::jsonb, 'draft'),
  ('alcohol-cancer', 'food', 'Alcohol raises cancer risk, and moderate drinking has no proven health benefit', 'Alcohol', 'Cancer and early death', 'Adults', 'increases', 'Alcohol is a Group 1 carcinogen linked to at least seven cancers. After correcting for study biases, low-volume drinking was not linked to longer life.', 'high', 'IARC classification for cancer; recent meta-analysis correcting earlier methodological biases about ''protective'' moderate drinking.', 'Less is better. The idea that a daily glass of wine protects your heart came largely from flawed comparisons and isn''t a reason to drink.', '[]'::jsonb, '[{"citation":"Zhao J et al. Association between daily alcohol intake and risk of all-cause mortality: a systematic review and meta-analyses. JAMA Network Open, 2023","design":"Meta-analysis of cohort studies","tier":3,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Zhao%20association%20between%20daily%20alcohol%20intake%20and%20risk%20of%20all-cause%20mortality%20meta-analyses%20JAMA%20Netw%20Open%202023"}]'::jsonb, 'draft'),
  ('coffee-health', 'food', 'Moderate coffee drinking is not harmful for most adults', 'Coffee (about 3-4 cups a day)', 'Early death and chronic disease', 'Adults, excluding pregnancy', 'decreases', 'An umbrella review linked 3-4 cups a day with slightly lower risk of early death and several diseases; pregnant people should limit caffeine.', 'low', 'Large body of observational evidence with possible confounding.', 'Coffee is fine and possibly mildly beneficial for most adults. Watch the sugar and syrups added to it, and limit caffeine during pregnancy.', '[]'::jsonb, '[{"citation":"Poole R et al. Coffee consumption and health: umbrella review of meta-analyses of multiple health outcomes. BMJ, 2017","design":"Umbrella review of meta-analyses","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Poole%20coffee%20consumption%20and%20health%20umbrella%20review%20of%20meta-analyses%20BMJ%202017"}]'::jsonb, 'draft'),
  ('breakfast-weight', 'timing', 'Skipping breakfast does not cause weight gain', 'Eating or skipping breakfast', 'Body weight and daily calorie intake', 'Adults', 'no_effect', 'In randomised trials, people who ate breakfast ate slightly more calories in total and did not lose more weight.', 'low', 'Meta-analysis of randomised trials that were short and of mixed quality.', 'Breakfast isn''t the most important meal for weight. Eat it if you''re hungry; skip it if you''re not.', '[]'::jsonb, '[{"citation":"Sievert K et al. Effect of breakfast on weight and energy intake: systematic review and meta-analysis of randomised controlled trials. BMJ, 2019","design":"Meta-analysis of randomised trials","tier":1,"url":"https://pubmed.ncbi.nlm.nih.gov/?term=Sievert%20effect%20of%20breakfast%20on%20weight%20and%20energy%20intake%20systematic%20review%20meta-analysis%20BMJ%202019"}]'::jsonb, 'draft')
on conflict (id) do update set
  category = excluded.category, title = excluded.title, exposure = excluded.exposure,
  outcome = excluded.outcome, population = excluded.population, direction = excluded.direction,
  effect = excluded.effect, confidence = excluded.confidence,
  confidence_reasons = excluded.confidence_reasons, summary = excluded.summary,
  triggers = excluded.triggers, sources = excluded.sources,
  review_status = excluded.review_status, updated_at = now();

insert into public.diets (id, name, claim_ids)
values
  ('none', 'No particular diet', array[]::text[]),
  ('mediterranean', 'Mediterranean', array['mediterranean-cvd', 'nuts-cvd', 'fish-heart', 'legumes-ldl']::text[]),
  ('keto', 'Keto / low-carb', array['low-carb-vs-low-fat', 'saturated-fat-replacement', 'fiber-chronic-disease']::text[]),
  ('carnivore', 'Carnivore', array['carnivore-long-term', 'fiber-chronic-disease', 'processed-meat-colorectal', 'saturated-fat-replacement']::text[]),
  ('vegan', 'Vegan', array['vegetarian-heart', 'vegan-b12', 'legumes-ldl']::text[]),
  ('vegetarian', 'Vegetarian', array['vegetarian-heart', 'vegan-b12']::text[]),
  ('intermittent-fasting', 'Intermittent fasting', array['intermittent-fasting-weight', 'breakfast-weight']::text[]),
  ('paleo', 'Paleo', array['paleo-short-term', 'whole-grains-cvd', 'legumes-ldl']::text[]),
  ('low-fat', 'Low-fat', array['low-carb-vs-low-fat', 'saturated-fat-replacement']::text[]),
  ('dash', 'DASH', array['dash-blood-pressure', 'sodium-blood-pressure']::text[])
on conflict (id) do update set name = excluded.name, claim_ids = excluded.claim_ids;
